// X-Hub-Signature-256 = 'sha256=' + HMAC-SHA256(сырое тело, META_APP_SECRET).
// Только по сырому телу: повторная сериализация JSON меняет байты (\uXXXX у Meta).
const crypto = require('crypto');
const item = $input.first();
const secret = $env.META_APP_SECRET;
const header = String(item.json.headers['x-hub-signature-256'] ?? '');
let valid = false;
if (secret && item.binary?.data) {
  const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  valid = header.length === expected.length
    && crypto.timingSafeEqual(Buffer.from(header), Buffer.from(expected));
}
return [{ json: { valid, body: item.json.body } }];

// Единая форма входящего Сообщения для всех Каналов:
// { channel, account_id, sender_id, provider_message_id, text }.
// Новый Канал = новая ветка здесь, остальной поток не меняется.
const body = $input.first().json.body ?? {};

function messenger(body) {
  const out = [];
  for (const entry of body.entry ?? []) {
    for (const event of entry.messaging ?? []) {
      const message = event.message;
      if (!message || message.is_echo || typeof message.text !== 'string') continue;
      out.push({
        channel: 'messenger',
        account_id: String(event.recipient.id),
        sender_id: String(event.sender.id),
        provider_message_id: message.mid,
        text: message.text,
      });
    }
  }
  return out;
}

const NORMALIZERS = { page: messenger };
const normalize = NORMALIZERS[body.object];
if (!normalize) return [];
return normalize(body).map((json) => ({ json }));
